var i=`0180-parmigiana-di-melanzane`;var t=`world-0180`;var n=`IT`;var r=`southern-europe`;var l=4;var o=92;var g={en:`Parmigiana di Melanzane`,ua:`Парміджана з баклажанів`};var s={en:`A classic dish from Italy, featuring eggplant, garlic, basil, mozzarella. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Італія. Основні складники: баклажан, часник, базилік, моцарела. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var u=[{en:`Cut the vegetables evenly and roast at 200°C for about 25 minutes until tender and lightly charred.`,ua:`Наріжте овочі рівномірно та запікайте при 200°C приблизно 25 хвилин до м’якості й легкої підпеченої скоринки.`,t:[`roasting`],m:25,i:[[`eggplant`,850,`g`],[`extra-virgin-olive-oil`,75,`ml`]]},{en:`Cook the listed sauce ingredients over medium-low heat for about 18 minutes until aromatic and slightly thickened.`,ua:`Готуйте складники соусу на помірно слабкому вогні приблизно 18 хвилин до появи аромату та легкого загустіння.`,t:[`sauteing`,`reducing-sauce`],m:18,i:[[`tomato-passata`,550,`g`],[`garlic`,4,`clove`],[`basil`,22,`g`]]},{en:`Layer the prepared elements evenly in the baking dish, spreading filling right to the edges.`,ua:`Викладіть підготовлені компоненти рівними шарами у формі, розподіляючи начинку до країв.`,t:[`layered-assembly`],m:16,i:[[`mozzarella`,380,`g`],[`parmigiano-reggiano`,140,`g`]]},{en:`Bake in a preheated 180°C oven for about 33 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 33 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:33,i:[]}];var d={slug:i,id:t,country:`IT`,region:r,servings:4,minutes:92,title:g,text:s,steps:u};export{n as country,d as default,t as id,o as minutes,r as region,l as servings,i as slug,u as steps,s as text,g as title};